INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fat Chicken', 'Fatten up the herds and rake in the cash - a REVERSE TOWER DEFENSE game where you build a factory farm armed to the udders with towers that provide feed and water to the oncoming herds of farm animals. Upgrade your towers to boost their efficiency and don''t forget to fend off pesky protesters with your well-armed force of rent-a-cops! Heck, you may even need to ward off a UFO or two!' FROM games WHERE igdb_id = 17891 ON CONFLICT (game_id, language_code) DO NOTHING;
