INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zamb! Biomutant Extermination', 'Play as two special operatives and fight your way through a mad scientist''s secret asteroid base whilst defending yourself against his army of evil mutants. Develop the skills of your agent, increase their power and overcome 24 uniquely challenging levels which get harder as you progress. Play solo, or draft in a loyal friend for epic co-op action. Use everything at your disposal in order to eliminate the mutant army and put a stop to their evil before it spreads across the universe.' FROM games WHERE igdb_id = 9299 ON CONFLICT (game_id, language_code) DO NOTHING;
