INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rube Works: The Official Rube Goldberg Invention Game', 'The first and only official Rube Goldberg puzzle game. Solve everyday problems in Rube’s trademark elaborate whimsical style by creating hilarious machines. Is pouring a glass of juice just too straightforward and boring? Try using a jack-in-the-box, magnifying glass, string and a cymbal-wielding friend to achieve your goal. The more creative your solution the better!' FROM games WHERE igdb_id = 17212 ON CONFLICT (game_id, language_code) DO NOTHING;
