INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abelardo: Steakhouse Musician', 'Play as Abelardo, a guitar-wielding dinosaur entertaining diners in a bustling steakhouse. Navigate between tables, match each customer’s requested music style, and perform rhythm sequences to earn “meat” while avoiding collisions that can end your run. Built in Unity and originally released as part of the Indies vs PewDiePie jam, it’s a single-player music/arcade experience presented from a top-down perspective.' FROM games WHERE igdb_id = 232001 ON CONFLICT (game_id, language_code) DO NOTHING;
