INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bernd das Brot und die Unmöglichen', 'Sehr zu Bernds Leidwesen muss er gemeinsam mit seinen Freunden die Welt retten. Also los! Hilf Bernd, Chili und Briegel, das Geheimnis um die Statue des "Erkälteten und Skat spielenden Yakks" zu lösen, verhöre Straßenpantomimen, leg dich mit wahnwitzigen Weltverschwörern an, reise auf einem Motorroller durch die Zeit, und stoppe die Invasion der Llamas! Und das alles in einem nicht atmungsaktiven Kostüm ... Armer Bernd!' FROM games WHERE igdb_id = 129882 ON CONFLICT (game_id, language_code) DO NOTHING;
