INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleach Online', 'Bleach Online is a browser-based Massive multi-player online role-playing game (MMORPG) from Gogames.me, a new game publisher devoted to bringing engaging and immersive online games to players everywhere. Available for all computers with an Internet connection, Bleach Onlinebrings the popular anime,”Bleach,” to web browsers, featuring original anime plots and the original Japanese anime art style.' FROM games WHERE igdb_id = 23623 ON CONFLICT (game_id, language_code) DO NOTHING;
