INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Landgrabbers', 'A adventure through the Middle Ages awaits you in the strategy game Landgrabbers. In this thrilling game, you embrace the historic role of a great military commander who is out to rule the entire world. You''ll have to fight your way across a variety of locations, each with its own special difficulties, with your mighty army. Are you prepared to go on this thrilling trip, then?' FROM games WHERE igdb_id = 95683 ON CONFLICT (game_id, language_code) DO NOTHING;
