INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wargame: France 1940', 'A classic hex and counter wargame, simulating the 1940 campaign in the West - the famous Fall of France, along with Belgium and Holland. The game is big, with over 300 units, mostly divisions, representing Germany, Holland, Belgium, Britain, France, and even Poland. There are infantry, fortresses, tanks (Panzers), parachutists, and more.' FROM games WHERE igdb_id = 108563 ON CONFLICT (game_id, language_code) DO NOTHING;
