INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie Magical Fashion', 'Barbie Magical Fashion lets players design their very own Barbie, mixing and matches different outfits, hairstyles, tiaras, makeup patterns, accessories, wings, mermaid tails, and more. Players can transform avatars into princesses, mermaids, fairies, or even create a unicorn. Each step is simple and uses touch mechanics to let players choose and customize. There is a special gift box minigame for each character, where if the player discovers and opens the magical gift box in the correct customization step, they will unlock its reward for all characters.' FROM games WHERE igdb_id = 261412 ON CONFLICT (game_id, language_code) DO NOTHING;
