INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Fantasy: Starship Traveller', 'Steve Jackson and Tin Man Games present Starship Traveller - an adventure of the far future in which you are the hero! Sucked through the appalling nightmare of the Seltsian Void, the starship Traveller emerges at the other side of the black hole into an unknown universe. You are the captain of the Traveller, and her fate lies in your hands. Will you be able to discover the way back to Earth from the alien peoples and planets you encounter, or will you and your crew be doomed to roam uncharted space forever?' FROM games WHERE igdb_id = 175052 ON CONFLICT (game_id, language_code) DO NOTHING;
