INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('epic-war-legends', 234263, '2014-12-31', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic War Legends', 'Epic War Legends was vastly different from any of the previous Epic War games. It was more of an RPG than a Strategy game. Players chose one of six heroes at the beginning, and there was a cost to change the hero. Players also equipped a main and reserve army; if a troop died the troop in the reserve would take over. Players clicked to walk, which depleted energy, and all events on their way were mandatory, except for vs PvP. During the battles players had no control, instead all troops including the hero attacked automatically until all troops on one side died, or the battle timed out (which the timer was not displayed).' FROM games WHERE igdb_id = 234263 ON CONFLICT (game_id, language_code) DO NOTHING;
