INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naval Tactics', 'From the hexagonal playing field to the potentially game changing Captain''s Cards, Naval Tactics is a board game to its very roots. To succeed you will need to take your time, think three moves ahead, and mind the weather gauge!
