INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1953: NATO vs Warsaw Pact', '1953: NATO vs Warsaw Pact is a strategic game about potential Cold War conflict just after the Stalin’s death. When the cruel tyrant has gone, Soviet warmongers has been finally able to start war with rotten West. With the nuclear power in the hands of both sides there is a huge possibility to end the world as we know it. How this ends, depend only on the action taken by both sides.' FROM games WHERE igdb_id = 17886 ON CONFLICT (game_id, language_code) DO NOTHING;
