INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snap-A-Game: Classic RPG', 'Make your own game! With Snap-A-Game RPG, you can snap together your own classic RPG within minutes! Put together your own enemies and NPC''s using over 60 body parts and over 1,000,000 possible character combinations! Build your own customized weapons and weapon shops; draw your own overworld maps using tiles for grass, snow, sand, stone and lava; and interlink as many overworld maps as you want for almost unlimited game play possibilities! NOTE: This program is for entertainment purposes only and is not for professional game development. These games cannot be sold and contain copyrighted material.' FROM games WHERE igdb_id = 288680 ON CONFLICT (game_id, language_code) DO NOTHING;
