INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neko Atsume: Kitty Collector', 'Attract cats with food and then watch them romp with your toys! More than 40 varieties of cats—white and black, tabby and calico—might stop by. Rare cats are rumored to roam the neighborhood too, but you''ll need particular items to entice those elusive felines. Each visitor is logged in your Catbook. Become a master kitty collector and fill it up!' FROM games WHERE igdb_id = 15699 ON CONFLICT (game_id, language_code) DO NOTHING;
