INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyro Jump', 'Leap from one wheel to another and try to catch Princess Paper in a hundred or so levels full of pitfalls. Pyro, the little flame, is burning with love for the princess and is ready to try anything to convince her that this romantic idyll is not destined to go up in flames! In each level, collect all the flames and unlock bonus levels!' FROM games WHERE igdb_id = 54272 ON CONFLICT (game_id, language_code) DO NOTHING;
