INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('call-of-duty-advanced-warfare-atlas-pro-edition', 102718, '2014-11-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4a7q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8weh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: Advanced Warfare - Atlas Pro Edition', 'Prepare for battle like never before with this Atlas Pro Edition, which is loaded with an arsenal of physical and digital content to equip you for this new age of warfare. Lock and load for combat with the Atlas digital content pack that includes the Bal-27 AE Assault Rifle and Atlas 45 AE Pistol, Atlas exoskeleton, helmet and player card, five bonus supply drops and a single-player exoskeleton upgrade token. Enhance your multiplayer gameplay right out of the gate with the Call of Duty: Advanced Warfare Season Pass, which features four additional, action-packed DLC map packs. Return to the fan-favorite Call of Duty 4: Modern Warfare map, Pipeline, that has been re-envisioned in the Atlas Gorge bonus multiplayer map, where you''re exploring and navigating the shadows of the Three Gorges Dam in central China. Make sure you''re fully equipped to become a tier-one Advanced Soldier with the Atlas Corporation with the Welcome to Atlas: Advanced Soldier Manual, which provides necessary intel and historical and tactical information to boost your potential in the field and features original concept artwork from Sledgehammer Games. Store and display your copy of the game in the collectible SteelBook, and kick back with the official Call of Duty: Advanced Warfare soundtrack. The future of war is upon you - are you ready to play your part?' FROM games WHERE igdb_id = 102718 ON CONFLICT (game_id, language_code) DO NOTHING;
