INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: Dire Grove, Sacred Grove', 'Dire Grove has been plunged into a record-defying cold, and wild animals threaten at every turn! You''ve been called in to uncover the source of the town''s troubles. But you quickly find yourself in the middle of a feud between the local hunters and the mysterious Mistwalkers who live in the woods. Can you prevent an all-out war? Pick your gender and use an innovative deduction mechanic as you try to discover the secret behind Dire Grove''s curse!' FROM games WHERE igdb_id = 140230 ON CONFLICT (game_id, language_code) DO NOTHING;
