INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foosball - Street Edition', 'Foosball - Street Edition is a 5 VS 5 arcade football game, that puts you in control of 9 teams of foosball players, each one with unique skills and abilities. Far from trying to imitate a football simulation like other games, Foosball - Street Edition focus in offering new game modes that take the player to a brand new and fresh approach into football. You have never played Bread & Cheese, Score to Win, Pass to Ten or any of the others. Are you ready?' FROM games WHERE igdb_id = 17113 ON CONFLICT (game_id, language_code) DO NOTHING;
