INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War Thunder: Ground Forces', 'Gaijin Entertainment will be bringing its military MMO game War Thunder: Ground Forces to the PS4 leading historical battles not only in the sky but also in land and sea. War Thunder: Ground Forces is from the renowned War Thunder series that gave fans and enthusiasts a next generation MMO combat game devoted to World War II. With military aviation, armored vehicles, and fleets, gamers can take part in massive online battles, fighting with real players all over the world.' FROM games WHERE igdb_id = 115024 ON CONFLICT (game_id, language_code) DO NOTHING;
