INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ore No Animism: Hell Chapter', 'A free Touhou-like game made in Danmakufu v0.12m with various animal characters. Gameplay revolves around score-extends by use of a screen-clearing attack charged by collecting point items via grazing / PoC. Much tougher than a typical Touhou-like game, and only has two difficulty levels. However, it features an "Another" Stage, a second kind of Extra Stage where each of the two player characters gets a unique stage, ending with a fight against the other character. Also contains ten boss special attacks, one for each character.' FROM games WHERE igdb_id = 171803 ON CONFLICT (game_id, language_code) DO NOTHING;
