INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: Advanced Warfare - Day Zero Edition', 'This Day Zero Edition features two custom weapons, the AK-12G Assault Rifle and Crossbow-B2. Finally, the Day Zero Edition also includes the Advanced Arsenal Bullet Brass exoskeleton and EM1 Quantum directed energy weapon. Play before the rest of the world with the Call of Duty: Advanced Warfare - Day Zero Edition.' FROM games WHERE igdb_id = 261088 ON CONFLICT (game_id, language_code) DO NOTHING;
