INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpdrive', 'Jumpdrive is a sandbox space sim set in an alternative future heavily inspired by classic 80s sci-fi. Fight, trade and explore in a massive procedurally generated galaxy of millions of planets and stars. Amass money and power, upgrade and purchase new ships, and one day create your own small fleet with a base to call home.' FROM games WHERE igdb_id = 36361 ON CONFLICT (game_id, language_code) DO NOTHING;
