INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Verde Station', 'Verde Station is a first-person story/experience game set on a space station. During your year long solo mission you begin to question the world around you. The game reacts in subtle ways to how you play. Aboard Verde Station, you will test your wits, question everything, and strain to keep your sanity. Welcome to solitude.' FROM games WHERE igdb_id = 17859 ON CONFLICT (game_id, language_code) DO NOTHING;
