INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dysan the Shapeshifter', 'There’s no better disguise than looking exactly like your enemy: Dysan the shapeshifter is an upcoming PC fantasy RPG, featuring the possibility of giving its players the opportunity to shape-shift into their enemies and even into any NPC creature to get unique opportunities to win battles and solve the game.' FROM games WHERE igdb_id = 8703 ON CONFLICT (game_id, language_code) DO NOTHING;
