INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gemsa', 'In this fast-paced puzzle game, line up gemstones in horizontal rows for points and added time; but it''s not that simple! Each level demands a different color of gemstone! Drag your finger across unwanted gems and they will shatter, leaving the good ones to fall into place. Stack them for big combos and big points! Watch for special items as well; touching a "B" symbol will destroy all gems of the same color that you touched. Touching a "C" symbol will convert gems of the color you touched into the color for that level!' FROM games WHERE igdb_id = 243966 ON CONFLICT (game_id, language_code) DO NOTHING;
