INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rival Stars Basketball', 'Rival Stars Basketball gives you the control. Draft extraordinary players, plan your strategy and unleash your team on real opponents from around the world in thrilling card battles. Make heat of the moment plays to gain the lead as tension builds. Then at pivotal moments get thrown into 3D on court action! Do you pass or do you go for the 3 pointer? Your choice can make or break your success.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 249385 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
