INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QuestRun', 'Challenging and fast-paced with a modern twist on old school RPG battle systems, QuestRun is unlike anything you have played before. A J-RPG inspired tactical game with rogue-like elements and deep engaging gameplay. You love RPGs but can go without in depth dialogues and scenario based text? QuestRun is for you - taking you to battle in various themed dungeons. Progress as far as you can with your chosen heroes, die in agony and try again! Apply new strategies, try new heroes, choose new perils and die anyway! Untimely, premature deaths await!' FROM games WHERE igdb_id = 17160 ON CONFLICT (game_id, language_code) DO NOTHING;
