INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('magus', 8577, '2014-02-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hsg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sfolyyn6o5zz5p1gt7x6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magus', 'In a world of fire and water, an unfathomable power waits. Magus has been imprisoned in a tower in the Waterfall Kingdom and tortured for years. His crime is unknown; his history is a mystery. He remains locked up, powerless, until a new prisoner named Kinna arrives and she aids him in his escape. So begins their journey to discover Magus’s true abilities—chroma magic, his innate talent to absorb power from the colors green, red, and purple in the surrounding environment to unleash deadly attacks. Along the way they must face the wrath of the Waterfall Kingdom and battle them to uncover Magus’s ultimate purpose. Why has this mysterious woman decided to help him? And why now, after all this time?' FROM games WHERE igdb_id = 8577 ON CONFLICT (game_id, language_code) DO NOTHING;
