INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('theatrhythm-final-fantasy-curtain-call', 5679, '2014-04-24', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2roh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1id4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theatrhythm Final Fantasy: Curtain Call', 'A sequel to the first FINAL FANTASY rhythm action game released in 2012, THEATRHYTHM FINAL FANTASY CURTAIN CALL expands on the original in every way with new gameplay modes, over 200 songs, and 60 playable characters. Featuring music that spans the full breadth of the storied FINAL FANTASY franchise, players tap along to the memorable beats and harmonies as the adorable, stylized characters battle and quest through their worlds. The music of over 20 titles is brought together in one package, fusing together the moving scores, cinematic visuals, and role-playing elements the series is known for.' FROM games WHERE igdb_id = 5679 ON CONFLICT (game_id, language_code) DO NOTHING;
