INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Qbeh-1: The Atlas Cube', 'Qbeh-1: The Atlas Cube is an atmospheric 1st-person puzzle platformer by Liquid Flower that takes players on an inspired quest through a variety of divergent worlds, each filled with new mysteries and secrets to uncover. In each world, players find special cubes that must be collected and used to navigate to the next portal. Some cubes will simply be used as stepping stones to new areas while others are imbued with magical properties such as gravity and propulsion.' FROM games WHERE igdb_id = 10746 ON CONFLICT (game_id, language_code) DO NOTHING;
