INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronology', 'Chronology is a mind-bending mix of puzzle, adventure and platform game where you defy time by manipulating the past and the future, in order to fix the present. Play as the Old Inventor and his sidekick The Snail, and take advantage of their special abilities - travel back and forth in time, stop time, manipulate objects and solve puzzles.' FROM games WHERE igdb_id = 10087 ON CONFLICT (game_id, language_code) DO NOTHING;
